        let stats = InlinedDataStats {
            record_count: INLINE_FLUSH_MAX_ROWS - 1,
            entry_count: INLINE_FLUSH_MAX_SEGMENTS,
            ipc_bytes: INLINE_FLUSH_MAX_BYTES - 1,
        };

        assert_eq!(inline_memtable_pressure(stats), None);
